########################################\r","# Question 4: Convert \"hello world\" to title case\r","print(\"\\nQuestion 4: Convert 'hello world' to title case\")\r","# Your code here\r","text = \"hello world\"\r","text.title()\r","#######################################################\r","# Question 5: Find the length of string \"Data Science\"\r","print(\"\\nQuestion 5: Find the length of string 'Data Science'\")\r","# Your code here\r","data = \"Data Science\"\r","len(data)\r","#######################################################\r","# Question 6: Replace all spaces with underscores in \"Machine Learning\"\r","print(\"\\nQuestion 6: Replace all spaces with underscores in 'Machine Learning'\")\r","# Your code here\r","course = \"Machine Learning\"\r","course.replace(\" \",\"_\")\r","#######################################################\r","# Question 7: Check if \"python\" is in \"Python Programming Language\"\r","print(\"\\nQuestion 7: Check if 'python' is in 'Python Programming Language'\")\r","# Your code here\r","text = \"Python Programming Language\"\r","if \"python\" in text:\r","  print(\"Yes\")\r","else:\r","  print(\"No\")\r","#######################################################\r","# Question 8: Extract the first 5 characters from \"Artificial Intelligence\"\r","print(\"\\nQuestion 8: Extract the first 5 characters from 'Artificial Intelligence'\")\r","# Your code here\r","course = \"Artificial Intelligence\"\r","course[0:6]\r","#######################################################\r","# Question 9: Convert \"UPPERCASE\" to lowercase\r","print(\"\\nQuestion 9: Convert 'UPPERCASE' to lowercase\")\r","# Your code here\r","text = \"DATA ENGINEER\"\r","text.lower()\r","\r","#######################################################\r","# Question 10: Remove all vowels from \"Computer Science\"\r","print(\"\\nQuestion 10: Remove all vowels from 'Computer Science'\")\r","# Your code here\r","word = \"Computer Science\"\r","result = \"\"\r","\r","for i in word:\r","  if i not in \"aeiou\":\r","    result = result+i\r","print(result)\r","#######################################################\r","# Question 11: Find the most frequent character in \"mississippi\"\r","print(\"\\nQuestion 11: Find the most frequent character in 'mississippi'\")\r","# Your code here\r","text = \"mississippi\"\r","max_count = 0\r","freq_string = \"\"\r","\r","for i in text:\r"," # print(text.count(i))\r","  if text.count(i) \u003e max_count:\r","    max_count = text.count(i)\r","    freq_string = i\r","print(freq_string)\r","########################################################\r","# Question 12: Check if two strings are anagrams: \"listen\" and \"silent\"\r","print(\"\\nQuestion 12: Check if two strings are anagrams: 'listen' and 'silent'\")\r","# Your code here\r","########################################################\r","# Question 13: Capitalize first letter of each word in \"python programming language\"\r","print(\"\\nQuestion 13: Capitalize first letter of each word in 'python programming language'\")\r","# Your code here\r","text = \"python programming language\"\r","text.capitalize()\r","#######################################################\r","# Question 14: Count consonants in \"Hello World\"\r","print(\"\\nQuestion 14: Count consonants in 'Hello World'\")\r","# Your code here\r","#######################################################\r","# Question 15: Find the longest word in \"Python is a programming language\"\r","print(\"\\nQuestion 15: Find the longest word in 'Python is a programming language'\")\r","# Your code here\r","word = \"Python is a programming language\"\r","words = word.split()\r","words\r","longest=max(words,key=len)\r","print(longest)\r","\r","#######################################################\r","# Question 16: Remove all punctuation from \"Hello, World! How are you?\"\r","print(\"\\nQuestion 16: Remove all punctuation from 'Hello, World! How are you?'\")\r","# Your code here\r","text = \"He